    def save_image(self, settings):
        
        #############################################
        ###### Plot one figure ######################
        
        #path = os.path.join(ROOT_DIR, "all_bg/")
        ROOT_DIR = self.file_dialog

        # Path 
        path = os.path.join(ROOT_DIR, datetime.datetime.now().strftime("%Y%m%d%H%M%S")) 

        os.mkdir(path) 
        os.mkdir(path + '/train/')
        os.mkdir(path + '/val/')

        if self.checkBoxSaveBinaryMask.isChecked():

          os.mkdir(path + '/train/binary_masks/')
          os.mkdir(path + '/val/binary_masks/')

        self.folder = path

        data_train = {}
        data_val = {}

        data_train_coco = {'info':{
                                "description": 'Synthetic data',
                                "year": str(datetime.date.today().year),
                                "contributor": "https://github.com/nataliaasaa",
                                "date_created": str(datetime.datetime.now())
                                },
                        'images':[],
                        'annotations':[],
                        'categories':[]
                        }
        data_val_coco = {'info':{
                                "description": 'Synthetic data',
                                "year": str(datetime.date.today().year),
                                "contributor": "https://github.com/nataliaasaa",
                                "date_created": str(datetime.datetime.now())
                                },
                        'images':[],
                        'annotations':[],
                        'categories':[]
                        }

        self.num_of_images = self.spinBoxNofImages.value()
       
        count = 0

        # Save image from generate synthetic
        self.import_thread = GenerateSyntheticThread(self.num_of_images, settings, 
                                                count, self.folder, data_train, 
                                                data_val, data_train_coco, 
                                                data_val_coco)
        
        # Save json files
        self.import_thread.finished_signal.connect(self.save_annotations)

        # Make progress bar and label visible
        self.progressBar.setVisible(True)
        self.progressBar.setRange(0, self.num_of_images*len(self.data_store.data_dict)-1)

        self.label_2.setVisible(True)
        self.label_2.setText('In Progress')

        # Update progress bar
        self.import_thread.progress.connect(self.update_progress_bar)
        
        # Inicie a thread
        self.import_thread.start()

    def save_annotations(self, data_train, data_val, data_train_coco, data_val_coco, count):
        
        train_json = os.path.join(self.folder + '/train/via_region_data.json')   
        val_json = os.path.join(self.folder + '/val/via_region_data.json')   
        train_coco = os.path.join(self.folder + '/train/instances_train.json')   
        val_coco = os.path.join(self.folder + '/val/instances_val.json')   

        with open(train_json, "w") as f:
                json.dump(data_train, f, ensure_ascii=False, indent=2)        

        with open(val_json, "w") as f:
                json.dump(data_val, f, ensure_ascii=False, indent=2) 

        with open(train_coco, "w") as f:
                json.dump(data_train_coco, f, ensure_ascii=False, indent=2)  

        with open(val_coco, "w") as f:
                json.dump(data_val_coco, f, ensure_ascii=False, indent=2)    

        self.label_2.setText('Process Finished')

    def plot_image(self, settings):

        
        # Get image from generate synthetic
        count = 0

        _, _, _, _, _, final_image, gt_image = SyntheticGenerator().generate_synthetic_data(1, 
                                                                    settings, count) 

        figure, (ax1, ax2) = plt.subplots(1, 2, facecolor='#F0F0F0', figsize=(6, 3), layout='constrained')
        plt.margins(x=0, y=0)
        # Create a canvas to render the figure
        self.canvas = FigureCanvasQTAgg(figure)

        ax1.clear()
        ax2.clear()

        ax1.imshow(final_image, cmap='gray')
        ax1.set_aspect('equal')  
        ax1.axis("off")

        ax2.imshow(gt_image)
        ax2.set_aspect('equal')  
        ax2.axis("off")
        
        self.canvas.draw()

