    def update_progress_bar(self, value):

        self.progressBar.setValue(value)

    def get_data_from_my_settings(self, index):
        
        if self.comboBoxChooseSetting.currentText() == "My Settings": 
            data = self.data_store.data_dict

            # Display error message if no Setting is Found
            if data == {}:

                # Create tab and layout
                self.tab = QtWidgets.QWidget()
                self.tab.setObjectName(f"error")
                
                self.gridLayout_2 = QtWidgets.QGridLayout(self.tab)
                self.gridLayout_2.setObjectName(f"gridLayout_error")

                # #Create scene and add it to GraphicsView
                self.LabelNoData = QtWidgets.QLabel(parent=self.tab)
                self.LabelNoData.setText("No Data Found. Create your setting in Create Data and Add Setting.")
                self.gridLayout_2.addWidget(self.LabelNoData, 0, 0, 1, 3)
                self.tabWidget.addTab(self.tab, f"Error")
                self.tabWidget.show()
                self.pushButtonRefresh.setVisible(True)  

            # When data is found
            else:  

                # self.comboBoxImportJson.setVisible(False)
                self.pushButtonRefresh.setVisible(True)     
           
                self.create_tabs(data)
                self.tabWidget.show()

        elif self.comboBoxChooseSetting.currentText() == "Import Json":   
            self.import_settings_json()
            self.pushButtonRefresh.setVisible(False)
            # # self.comboBoxImportJson.setVisible(True)
            # # self.comboBoxImportJson.clicked.connect(self.import_settings_json)

        elif self.comboBoxChooseSetting.currentText() == "Presets":  
            # self.comboBoxImportJson.setVisible(False)
            self.pushButtonRefresh.setVisible(False)
            dlg = QtWidgets.QMessageBox(self)
            dlg.setWindowTitle("Warning!")
            dlg.setText('''<font color = '#335674'>Selecting the Presets option will delete any settings you 
                        might have created in the \"Create Settings\" page. Do you
                        wish to continue?''')
            dlg.setStandardButtons(QtWidgets.QMessageBox.StandardButton.Yes | QtWidgets.QMessageBox.StandardButton.No)
          
            button = dlg.exec()

            if button == QtWidgets.QMessageBox.StandardButton.Yes:
                self.data_store.data_dict = PRESETS
                self.create_tabs(self.data_store.data_dict)
                self.tabWidget.show()
  
        else:
            self.tabWidget.hide()
            # self.comboBoxImportJson.setVisible(False)

    def remove_settings_add_itens(self):
        data = self.data_store.data_dict
        self.comboBoxRemoveSetting.clear()
        for key in data:
            self.comboBoxRemoveSetting.addItems([key])   

    def remove_setting(self):
        delete_key = self.comboBoxRemoveSetting.currentText()
        data = self.data_store.data_dict
        del data[delete_key]   
        self.remove_settings_add_itens()
        self.create_tabs(data)
           

