    def import_settings_json(self):

        dlg = QtWidgets.QMessageBox(self)
        dlg.setWindowTitle("Warning!")
        dlg.setText("<font color = '#335674'>Importing a Json File will overwrite any \"My Settings\" that you might have.\n \
                    If that is the case, export your own settings before proceeding.</font color = '#335674'>")
        button = dlg.exec()

        file_dialog = QtWidgets.QFileDialog(directory='./')
        file_dialog.setFileMode(QtWidgets.QFileDialog.FileMode.ExistingFile)
        file_dialog.setNameFilter("Arquivos Json (*.json);;Todos os arquivos (*)")

        if file_dialog.exec() == QtWidgets.QFileDialog.DialogCode.Accepted:
            self.file_path  = file_dialog.selectedFiles()[0]
            # Opening the JSON file
            f = open(self.file_path)
            data = json.load(f)
            # Update data_dict
            self.data_store.data_dict = data
            self.create_tabs(data)
            self.tabWidget.show()

    # Create tabs according to the number of settings
    def create_tabs(self, data):
        
        self.tabWidget.clear()  # Clear existing tabs

        for key in data:

            # Activate Plot Mask setting            
            data[key]['plot_mask'] = True
            data[key]['save'] = False
            data[key]['train_val_ratio'] = 0
            data[key]['binary_mask'] = self.checkBoxSaveBinaryMask.isChecked()

            # Create tab and layout
            self.tab = QtWidgets.QWidget()
            self.tab.setObjectName(f"tab_{key}")
            
            self.gridLayout_2 = QtWidgets.QGridLayout(self.tab)
            self.gridLayout_2.setObjectName(f"gridLayout_{key}")

            # #Create scene and add it to GraphicsView
            # self.scene = QtWidgets.QLabel(parent=self.tab)
            # sizePolicy = QtWidgets.QSizePolicy(QtWidgets.QSizePolicy.Policy.Expanding, QtWidgets.QSizePolicy.Policy.Expanding)
            # sizePolicy.setHeightForWidth(self.scene.sizePolicy().hasHeightForWidth())
            # self.scene.setSizePolicy(sizePolicy) 
            # self.scene.setScaledContents(True)
            # # self.scene.setAlignment(QtCore.Qt.AlignmentFlag.AlignTop | QtCore.Qt.AlignmentFlag.AlignLeft)  
            # self.scene.setObjectName("scene")
 
            # Plot the settings in loop: send to plot_image one key/value at a time
            individual_settings = dict()
            individual_settings[key] = data[key].copy()
            # Activate Plot Mask setting            
            individual_settings[key]['plot_mask'] = True

            self.plot_image(individual_settings)

            self.gridLayout_2.addWidget(self.canvas, 0, 0, 1, 1)
            
            self.tabWidget.addTab(self.tab, f"{individual_settings[key]['class_name']}")
    
    # Show or hide the double spin box based on the checkbox state
    def handle_checkbox(self, state, widget1, widget2):

        if state == 2:
            widget1.setVisible(True)
            widget2.setVisible(True)
        else:
            widget1.setVisible(False)
            widget2.setVisible(False)

    def select_path_and_generate_data(self):

        file_dialog = QtWidgets.QFileDialog(directory='./')
        file_dialog.setFileMode(QtWidgets.QFileDialog.FileMode.Directory)
        
        if file_dialog.exec() == QtWidgets.QFileDialog.DialogCode.Accepted:

            self.file_dialog = file_dialog.selectedFiles()[0]

            data = self.data_store.data_dict

            if data == {}:

                error_message = "No Settings Found!"
                QtWidgets.QMessageBox.warning(self, "Generate Data Error", error_message)

            else:          
            
                for key in data:
         
                    data[key]['plot_mask'] = False
                    data[key]['save'] = True
                    data[key]['train_val_ratio'] = self.doubleSpinBoxTrainTest.value()
                    data[key]['binary_mask'] = self.checkBoxSaveBinaryMask.isChecked()
                self.save_image(data)
         
    def select_path_save_json(self):

        data = self.data_store.data_dict

        if data == {}:

            error_message = "No Setting Found! Create your setting on \"Create Data\" page or import a JSON"
            QtWidgets.QMessageBox.warning(self, "Empty Data error", error_message)
        
        else:

            fileName, _ = QtWidgets.QFileDialog.getSaveFileName(self, "Save JSON File", "", "JSON Files (*.json);;All Files (*)")
            
            if fileName:

                self.jsonFilePath = fileName
                
                with open(fileName, "w") as f:
                    json.dump(data, f, ensure_ascii=False, indent=2)  
                    
    def show_label(self):

        self.label_2.setVisible(True)
        self.label_2.setText('Process Started')

